from src.dataproc import process_items, load_data


def test_process_items():
    assert process_items([1, 2, 3]) == [2, 4, 6]


def test_process_skips_negative():
    assert process_items([-1, 2, -3, 4]) == [4, 8]


def test_load_data():
    assert load_data("source") == [1, 2, 3]


def test_load_data_empty_raises():
    import pytest
    with pytest.raises(ValueError):
        load_data("")
